25	/**
26	 * MQTT Properties container
27	 * */
28	public final class MqttProperties {
29	
30	    // single byte properties
31	    public static final int PAYLOAD_FORMAT_INDICATOR = 0x01;
32	    public static final int REQUEST_PROBLEM_INFORMATION = 0x17;
33	    public static final int REQUEST_RESPONSE_INFORMATION = 0x19;
34	    public static final int MAXIMUM_QOS = 0x24;
