37	    public static final int SUBSCRIPTION_IDENTIFIER_AVAILABLE = 0x29;
38	    public static final int SHARED_SUBSCRIPTION_AVAILABLE = 0x2A;
39	
40	    // two bytes properties
41	    public static final int SERVER_KEEP_ALIVE = 0x13;
42	    public static final int RECEIVE_MAXIMUM = 0x21;
43	    public static final int TOPIC_ALIAS_MAXIMUM = 0x22;
44	    public static final int TOPIC_ALIAS = 0x23;
45	
46	    // four bytes properties
47	    public static final int PUBLICATION_EXPIRY_INTERVAL = 0x02;
48	    public static final int SESSION_EXPIRY_INTERVAL = 0x11;
49	    public static final int WILL_DELAY_INTERVAL = 0x18;
50	    public static final int MAXIMUM_PACKET_SIZE = 0x27;
51	
52	    // Variable Byte Integer
53	    public static final int SUBSCRIPTION_IDENTIFIER = 0x0B;
54	
55	    // UTF-8 Encoded String properties
56	    public static final int CONTENT_TYPE = 0x03;
57	    public static final int RESPONSE_TOPIC = 0x08;
58	    public static final int ASSIGNED_CLIENT_IDENTIFIER = 0x12;
59	    public static final int AUTHENTICATION_METHOD = 0x15;
60	    public static final int RESPONSE_INFORMATION = 0x1A;
