62	    public static final int REASON_STRING = 0x1F;
63	    public static final int USER_PROPERTY = 0x26;
64	
65	    // Binary Data
66	    public static final int CORRELATION_DATA = 0x09;
67	    public static final int AUTHENTICATION_DATA = 0x16;
